catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    g_form.setReadOnly('assigne_task', false);
    g_form.setReadOnly('completed_task', false);
    g_form.setReadOnly('pending_task', false);
    g_form.setReadOnly('self_review', false);
    var emp = g_form.getValue('employee');
    if (!emp) return;

    var ga = new GlideAjax('x_594089_employe_0.getPerformanceData');
    ga.addParam('sysparm_name', 'getPerformance');
    ga.addParam('sysparm_employee', emp);
    ga.addParam('sysparm_period', newValue);
    ga.getXMLAnswer((response) => {
        console.log(response)
        var data = JSON.parse(response);
        if (data.assigned_task != '' && data.completed_task != '') {
            g_form.setValue('assigne_task', data.assigned_task);
            g_form.setValue('completed_task', data.completed_task);
            g_form.setValue('pending_task', data.pending_task);
            g_form.setValue('self_review', data.self_review);
            // g_form.setValue('review_period', data.period);
            g_form.setReadOnly('assigne_task', true);
            g_form.setReadOnly('completed_task', true);
            g_form.setReadOnly('pending_task', true);
            g_form.setReadOnly('self_review', true);
            // g_form.setReadOnly('review_period', true);
        }
    });
}
